#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/aes.h>

typedef struct gcm128_context GCM128_CONTEXT;
extern void CRYPTO_gcm128_init(GCM128_CONTEXT *ctx, void *key, void (*block)(const unsigned char in[16], unsigned char out[16], const void *key));
extern void CRYPTO_gcm128_setiv(GCM128_CONTEXT *ctx, const unsigned char *iv, size_t len);
extern int CRYPTO_gcm128_aad(GCM128_CONTEXT *ctx, const unsigned char *aad, size_t len);
extern int CRYPTO_gcm128_encrypt(GCM128_CONTEXT *ctx, const unsigned char *in, unsigned char *out, size_t len);
extern int CRYPTO_gcm128_encrypt_ctr32(GCM128_CONTEXT *ctx, const unsigned char *in, unsigned char *out, size_t len, void (*ctr)(const unsigned char *in, unsigned char *out, size_t blocks, const void *key, const unsigned char ivec[16]));
extern int CRYPTO_gcm128_finish(GCM128_CONTEXT *ctx, const unsigned char *tag, size_t len);
extern void CRYPTO_gcm128_tag(GCM128_CONTEXT *ctx, unsigned char *tag, size_t len);

extern void AES_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern int AES_set_encrypt_key(const unsigned char *userKey, const int bits, AES_KEY *key);

int main() {
    size_t n = 60000ULL*1024;
    unsigned char *pt = malloc(n);
    unsigned char *out = malloc(n);
    memset(pt, 0x42, n);
    unsigned char key[16];
    memset(key, 1, 16);
    unsigned char iv[12];
    memset(iv, 2, 12);
    AES_KEY aeskey;
    AES_set_encrypt_key(key, 128, &aeskey);

    /* GCM128_CONTEXT size: let's over-allocate */
    unsigned char ctxbuf[4096];
    memset(ctxbuf, 0, sizeof(ctxbuf));
    GCM128_CONTEXT *ctx = (GCM128_CONTEXT*)ctxbuf;

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    CRYPTO_gcm128_init(ctx, &aeskey, (void*)AES_encrypt);
    CRYPTO_gcm128_setiv(ctx, iv, 12);
    CRYPTO_gcm128_encrypt(ctx, pt, out, n);
    unsigned char tag[16];
    CRYPTO_gcm128_tag(ctx, tag, 16);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("low-level encrypt %.4f s  tag0=%02x\n", dt, tag[0]);
    return 0;
}
EOF
