#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/evp.h>

static void dump_ptrs(const char *label, unsigned char *base, int nbytes) {
    printf("-- %s (%p) --\n", label, base);
    for (int off = 0; off < nbytes; off += 8) {
        uint64_t v = *(uint64_t*)(base + off);
        if (v > 0x100000000ULL && v < 0x800000000000ULL)
            printf("  off %3d: %p\n", off, (void*)v);
        else if (v != 0 && v < 0x10000)
            printf("  off %3d: small %llu\n", off, (unsigned long long)v);
    }
}

int main() {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    unsigned char key[16]; memset(key, 0x11, 16);
    unsigned char iv[12]; memset(iv, 0x22, 12);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);

    unsigned char *p = (unsigned char*)ctx;
    void *cd = *(void**)(p + 176);   /* candidate cipher_data */
    printf("cipher_data candidate %p\n", cd);
    dump_ptrs("cipher_data", cd, 512);

    /* also dump the ctx itself fully for small ints */
    printf("-- ctx small fields --\n");
    for (int off = 0; off < 256; off += 4) {
        uint32_t v = *(uint32_t*)(p + off);
        if (v && v < 100000) printf("  off %3d: %u\n", off, v);
    }
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
EOF
