#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/evp.h>

typedef struct gcm128_context GCM128_CONTEXT;
extern int CRYPTO_gcm128_encrypt_ctr32(GCM128_CONTEXT *ctx, const unsigned char *in,
    unsigned char *out, size_t len,
    void (*ctr)(const unsigned char *in, unsigned char *out, size_t blocks,
                const void *key, const unsigned char ivec[16]));
extern void CRYPTO_gcm128_tag(GCM128_CONTEXT *ctx, unsigned char *tag, size_t len);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
    size_t blocks, const void *key, const unsigned char ivec[16]);

int main() {
    size_t n = 4*1024*1024; /* 4 MB first for correctness, then 60MB */
    unsigned char *pt = malloc(n);
    unsigned char *out = malloc(n);
    memset(pt, 0x42, n);
    unsigned char key[16]; for (int i=0;i<16;i++) key[i]=i+1;
    unsigned char iv[12]; for (int i=0;i<12;i++) iv[i]=i+0x10;
    unsigned char aad[32]; memset(aad, 0xab, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    int ol = 0;
    EVP_EncryptUpdate(ctx, NULL, &ol, aad, 32);  /* sets up gcm128 with AAD */

    unsigned char *base = (unsigned char*)ctx;
    unsigned char *cd = *(unsigned char**)(base + 176);
    GCM128_CONTEXT *gctx = *(GCM128_CONTEXT**)(cd + 0xe8);
    void *ks = *(void**)(cd + 0xf0);
    printf("gctx=%p ks=%p\n", gctx, ks);

    /* reference via normal EVP */
    unsigned char *ref = malloc(n+16);
    EVP_CIPHER_CTX *ctx2 = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx2, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx2, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx2, NULL, NULL, key, iv);
    int l=0, tot=0;
    EVP_EncryptUpdate(ctx2, NULL, &l, aad, 32);
    EVP_EncryptUpdate(ctx2, ref, &l, pt, n); tot=l;
    EVP_EncryptFinal_ex(ctx2, ref+tot, &l); tot+=l;
    unsigned char tagref[16];
    EVP_CIPHER_CTX_ctrl(ctx2, EVP_CTRL_GCM_GET_TAG, 16, tagref);

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int rc = CRYPTO_gcm128_encrypt_ctr32(gctx, pt, out, n, aesni_ctr32_encrypt_blocks);
    unsigned char tag[16];
    CRYPTO_gcm128_tag(gctx, tag, 16);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec-t0.tv_sec) + (t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("rc=%d time=%.4f match_ct=%d match_tag=%d\n", rc, dt,
        memcmp(out, ref, n)==0, memcmp(tag, tagref, 16)==0);
    printf("tag "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
    printf("ref "); for(int i=0;i<16;i++) printf("%02x", tagref[i]); printf("\n");

    /* throughput on 60MB */
    size_t N = 60000ULL*1024;
    unsigned char *big = malloc(N);
    unsigned char *bigout = malloc(N);
    memset(big, 0x42, N);
    /* reinit */
    EVP_CIPHER_CTX_reset(ctx);
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    EVP_EncryptUpdate(ctx, NULL, &ol, aad, 32);
    cd = *(unsigned char**)(base + 176);
    gctx = *(GCM128_CONTEXT**)(cd + 0xe8);
    clock_gettime(CLOCK_MONOTONIC, &t0);
    CRYPTO_gcm128_encrypt_ctr32(gctx, big, bigout, N, aesni_ctr32_encrypt_blocks);
    CRYPTO_gcm128_tag(gctx, tag, 16);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    dt = (t1.tv_sec-t0.tv_sec) + (t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("60MB time=%.4f  (%.0f MB/s)\n", dt, (N/1e6)/dt);
    return 0;
}
EOF
clang -O3 -o gcm_hw gcm_hw.c -I/usr/local/opt/openssl@3/include -L/usr/local/opt/openssl@3/lib -lcrypto && ./gcm_hw"}

