#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <openssl/evp.h>

int main() {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    unsigned char key[16]; for (int i=0;i<16;i++) key[i]=i;
    unsigned char iv[12]; memset(iv, 0x22, 12);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
    int ol=0; unsigned char aad[4]={1,2,3,4};
    EVP_EncryptUpdate(ctx, NULL, &ol, aad, 4);

    unsigned char *base = (unsigned char*)ctx;
    unsigned char *cd = *(unsigned char**)(base + 176);

    /* scan cd for pointers and dereference one level */
    for (int off = 0; off < 1600; off += 8) {
        uint64_t v = *(uint64_t*)(cd + off);
        if (v > 0x100000000ULL && v < 0x800000000000ULL) {
            printf("cd+%04x -> %p\n", off, (void*)v);
        }
    }
    /* also scan the ctx object for any pointer whose target contains the iv bytes */
    printf("--- scanning ctx region for IV bytes ---\n");
    unsigned char ivpat[12]; memset(ivpat, 0x22, 12);
    for (int off = 0; off < 512; off += 8) {
        uint64_t v = *(uint64_t*)(base + off);
        if (v > 0x100000000ULL && v < 0x800000000000ULL) {
            unsigned char *t = (unsigned char*)v;
            for (int k = 0; k < 4096-12; k++) {
                if (memcmp(t+k, ivpat, 12)==0) { printf("IV found via ctx+%d -> +%d\n", off, k); break; }
            }
        }
    }
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
EOF
