#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec + t.tv_nsec/1e9; }

typedef struct { unsigned char *in, *out; size_t off, len; unsigned char key[16]; unsigned char iv[16]; } job_t;

static void *worker(void *arg) {
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, j->key, j->iv);
    int l=0; size_t done=0;
    while (done < j->len) {
        int chunk = (j->len-done > 1<<30) ? 1<<30 : (int)(j->len-done);
        EVP_EncryptUpdate(ctx, j->out + j->off + done, &l, j->in + j->off + done, chunk);
        done += l;
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    size_t N = 60000ULL*1024;
    unsigned char *in = malloc(N), *out = malloc(N);
    memset(in, 0x42, N);
    unsigned char key[16]; memset(key, 1, 16);
    unsigned char iv[16]; memset(iv, 2, 16);

    for (int threads = 1; threads <= 6; threads++) {
        double t0 = now();
        pthread_t th[8]; job_t jobs[8];
        size_t chunk = (N/threads) & ~((size_t)15);
        for (int i = 0; i < threads; i++) {
            jobs[i].in = in; jobs[i].out = out;
            jobs[i].off = i*chunk;
            jobs[i].len = (i==threads-1) ? N - i*chunk : chunk;
            memcpy(jobs[i].key, key, 16);
            memcpy(jobs[i].iv, iv, 16);
            /* NOTE: iv not adjusted per chunk — this is throughput only */
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        for (int i = 0; i < threads; i++) pthread_join(th[i], NULL);
        double dt = now()-t0;
        printf("%d threads: %.4f s (%.0f MB/s)\n", threads, dt, (N/1e6)/dt);
    }
    return 0;
}
EOF
