    printf("tag = "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    /* J0 = iv || 0x00000001 */
    unsigned char J0[16]; memcpy(J0, iv, 12); J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
