    unsigned char mytag[16];
    for (int i=0;i<16;i++) mytag[i] = gh_out[i] ^ EJ0[i];
    printf("mytag = "); for(int i=0;i<16;i++) printf("%02x", mytag[i]); printf("\n");
    printf("MATCH %d\n", memcmp(mytag, tag, 16)==0);
    return 0;
}
