    __m128i tmp1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i tmp2 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i tmp3 = _mm_clmulepi64_si128(a, b, 0x10);
    tmp2 = _mm_xor_si128(tmp2, tmp3);
    tmp3 = _mm_slli_si128(tmp2, 8);
    tmp2 = _mm_srli_si128(tmp2, 8);
    tmp0 = _mm_xor_si128(tmp0, tmp3);
    tmp1 = _mm_xor_si128(tmp1, tmp2);
    /* reduction mod reflected polynomial */
    __m128i t = _mm_srli_epi64(tmp0, 63);
    __m128i t2 = _mm_srli_epi64(tmp0, 62);
    __m128i t3 = _mm_srli_epi64(tmp0, 57);
    t = _mm_xor_si128(t, _mm_xor_si128(t2, t3));
    __m128i carry = _mm_slli_si128(t, 8); /* move high dword-lane carry... use shuffle */
    /* The canonical reduction from the whitepaper uses shifts of the whole 128-bit value.
       Implement exactly: */
    __m128i X0 = tmp0, X1 = tmp1;
    __m128i v1 = _mm_slli_epi64(X0, 1);
    __m128i v2 = _mm_slli_epi64(X0, 2);
    __m128i v7 = _mm_slli_epi64(X0, 7);
    __m128i v = _mm_xor_si128(v1, _mm_xor_si128(v2, v7));
    /* account for cross-lane bits: bits shifted out of low 64 into high 64 */
    __m128i xtra = _mm_srli_epi64(X0, 63);
    xtra = _mm_slli_si128(xtra, 8);
    __m128i xtra2 = _mm_srli_epi64(X0, 62); xtra2 = _mm_slli_si128(xtra2, 8);
    __m128i xtra7 = _mm_srli_epi64(X0, 57); xtra7 = _mm_slli_si128(xtra7, 8);
    v = _mm_xor_si128(v, _mm_xor_si128(xtra, _mm_xor_si128(xtra2, xtra7)));
    X0 = _mm_xor_si128(X0, v);
    /* second phase: right shifts */
    __m128i w1 = _mm_srli_epi64(X0, 1);
    __m128i w2 = _mm_srli_epi64(X0, 2);
    __m128i w7 = _mm_srli_epi64(X0, 7);
    __m128i w = _mm_xor_si128(w1, _mm_xor_si128(w2, w7));
    __m128i ytra = _mm_slli_epi64(_mm_srli_si128(X0, 8), 63);
    __m128i ytra2 = _mm_slli_epi64(_mm_srli_si128(X0, 8), 62);
    __m128i ytra7 = _mm_slli_epi64(_mm_srli_si128(X0, 8), 57);
    w = _mm_xor_si128(w, _mm_xor_si128(ytra, _mm_xor_si128(ytra2, ytra7)));
    return _mm_xor_si128(X1, _mm_xor_si128(X0, w));
}

/* reference */
typedef struct { uint64_t hi, lo; } u128;
static u128 load_be(const unsigned char *p){u128 r={0,0};for(int i=0;i<8;i++)r.hi=(r.hi<<8)|p[i];for(int i=0;i<8;i++)r.lo=(r.lo<<8)|p[8+i];return r;}
static u128 xor128(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
static u128 shr1(u128 a){a.lo=(a.lo>>1)|(a.hi<<63);a.hi>>=1;return a;}
static u128 gmul_ref(u128 x,u128 h){u128 z={0,0},v=h;for(int i=0;i<64;i++){if((x.hi>>(63-i))&1)z=xor128(z,v);int l=v.lo&1;v=shr1(v);if(l)v.hi^=0xe100000000000000ULL;}for(int i=0;i<64;i++){if((x.lo>>(63-i))&1)z=xor128(z,v);int l=v.lo&1;v=shr1(v);if(l)v.hi^=0xe100000000000000ULL;}return z;}

int main(){
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    unsigned char zero[16]={0};
    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new();
