typedef struct { uint64_t hi, lo; } u128;
static u128 load_be(const unsigned char *p){u128 r={0,0};for(int i=0;i<8;i++)r.hi=(r.hi<<8)|p[i];for(int i=0;i<8;i++)r.lo=(r.lo<<8)|p[8+i];return r;}
