static __m128i red_C(__m128i lo, __m128i hi) {
    /* two-phase shift reduction, whole-register shifts via byte shifts */
    __m128i v = _mm_xor_si128(_mm_xor_si128(_mm_slli_epi64(lo,1), _mm_slli_epi64(lo,2)), _mm_slli_epi64(lo,7));
