/* 256-bit right shift by k (k<=64), across two __m128i (lo = bits 0..127, hi = bits 128..255) */
static void shr256(__m128i *lo, __m128i *hi, int k) {
    /* shift the 4x64 lanes */
    uint64_t L[2], H[2];
    _mm_storeu_si128((__m128i*)L, *lo);
    _mm_storeu_si128((__m128i*)H, *hi);
    unsigned __int128 v0 = ((unsigned __int128)L[1] << 64) | L[0];
    unsigned __int128 v1 = ((unsigned __int128)H[1] << 64) | H[0];
    v0 = (v0 >> k) | ((unsigned __int128)(v1 & (((unsigned __int128)1<<k)-1)) << (128-k));
    v1 >>= k;
    L[0]=v0; L[1]=v0>>64; H[0]=v1; H[1]=v1>>64;
    *lo = _mm_loadu_si128((__m128i*)L); *hi = _mm_loadu_si128((__m128i*)H);
