    /* w[0]=bits0-63 ... w[3]=bits192-255. Reduce w[3] then w[2] into lower. */
    for (int lane = 3; lane >= 2; lane--) {
        uint64_t v = w[lane];
        /* x^(64*lane) = x^(64*(lane-2)) * x^128 = x^(64*(lane-2)) * (x^7+x^2+x+1) */
        int base = 64*(lane-2);
        /* add v shifted by base+0, base+1, base+2, base+7 */
        int shifts[4] = {0,1,2,7};
        for (int s = 0; s < 4; s++) {
            int sh = base + shifts[s];
            int dst = sh / 64; int off = sh % 64;
            w[dst] ^= v << off;
            if (off && dst+1 < 4) w[dst+1] ^= v >> (64-off);
        }
        w[lane] = 0;
    }
    return _mm_loadu_si128((__m128i*)w);
