   Use 256-entry table per byte nibble? 4-bit table: 16 entries of 128 bits, 8 lookups per block = slow.
   Use 8-bit tables: 16 tables * 256 * 16 = 64KB. One lookup per byte. */
typedef struct { u128 T[16][256]; } ghash_tab;

static u128 shl1(u128 a, int *carry){int c=a.hi>>63;a.hi=(a.hi<<1)|(a.lo>>63);a.lo<<=1;*carry=c;return a;}
