   with gmul_ref which shifts RIGHT and xors 0xe1 into the top byte when LSB set. So "multiply by x"
   in that convention is a right shift. Tables should be built with the same op as gmul_ref. */

static u128 mul_x_ref(u128 v){ /* the per-bit step of gmul_ref: shr1 + conditional xor */
    int lsb = v.lo & 1; v.lo = (v.lo>>1)|(v.hi<<63); v.hi >>= 1; if (lsb) v.hi ^= 0xe100000000000000ULL; return v;
}

static void tab_init(ghash_tab *t, u128 H){
    for (int byte = 0; byte < 16; byte++){
        for (int v = 0; v < 256; v++){
            u128 acc={0,0}, h=H;
            /* byte position: byte 0 is the most significant byte (bits 127..120) */
            int bitbase = 120 - 8*byte;
            for (int b = 0; b < 8; b++){
                if ((v >> (7-b)) & 1){
