/* Verify clmul lane ordering: clmul(x, h, 0x00) = low64(x) * low64(h), result bits 0..127
   where bit 0 of a lane is the least significant bit. */
int main(){
    unsigned char xb[16]={0}, hb[16]={0};
    xb[0]=0x02; /* low byte = 2 */
    hb[0]=0x03;
    __m128i x=_mm_loadu_si128((__m128i*)xb);
    __m128i h=_mm_loadu_si128((__m128i*)hb);
    __m128i r=_mm_clmulepi64_si128(x,h,0x00);
    unsigned char o[16]; _mm_storeu_si128((__m128i*)o, r);
    printf("2*3 = "); for(int i=0;i<16;i++) printf("%02x", o[i]); printf(" (expect 06 at byte0)\n");

    /* bit 63 * bit 63 = bit 126 */
    memset(xb,0,16); memset(hb,0,16);
    xb[7]=0x80; hb[7]=0x80;
    x=_mm_loadu_si128((__m128i*)xb); h=_mm_loadu_si128((__m128i*)hb);
    r=_mm_clmulepi64_si128(x,h,0x00);
    _mm_storeu_si128((__m128i*)o, r);
    printf("bit63*bit63 = "); for(int i=0;i<16;i++) printf("%02x", o[i]); printf(" (expect bit126 = byte15 bit0x40)\n");

    /* cross lane: imm 0x01 = low64(x)*high64(h)? Check docs: imm[0]=src2 low/high, imm[4]=src1.
       0x00: both low. 0x01: x low, h high. 0x10: x high, h low. 0x11 both high. */
    memset(xb,0,16); memset(hb,0,16);
    xb[0]=0x02; hb[8]=0x03; /* h high lane = 3 */
    x=_mm_loadu_si128((__m128i*)xb); h=_mm_loadu_si128((__m128i*)hb);
    r=_mm_clmulepi64_si128(x,h,0x01);
    _mm_storeu_si128((__m128i*)o, r);
    printf("imm 0x01 (2 * 3 in high lane of h) = "); for(int i=0;i<16;i++) printf("%02x", o[i]); printf("\n");
    return 0;
}
