#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <openssl/evp.h>

/* Bit-reverse each byte, no byte swap: maps GCM byte order (byte0 = x^127..x^120, MSB=x^127)
   onto reflected order (byte0 bit0 = x^127). Combined with clmul's low-bit-is-x^0 convention
   this is exactly the reflected representation. */
static inline __m128i bitrev8(__m128i x){__m128i m1=_mm_set1_epi8(0x0f);__m128i l=_mm_and_si128(x,m1);__m128i h=_mm_and_si128(_mm_srli_epi16(x,4),m1);const __m128i lut=_mm_set_epi8(0x0,0x8,0x4,0xc,0x2,0xa,0x6,0xe,0x1,0x9,0x5,0xd,0x3,0xb,0x7,0xf);l=_mm_shuffle_epi8(lut,l);h=_mm_shuffle_epi8(lut,h);return _mm_or_si128(_mm_slli_epi16(l,4),h);}

typedef struct { uint64_t hi, lo; } u128;
static u128 load_be(const unsigned char *p){u128 r={0,0};for(int i=0;i<8;i++)r.hi=(r.hi<<8)|p[i];for(int i=0;i<8;i++)r.lo=(r.lo<<8)|p[8+i];return r;}
static u128 xor128(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
static u128 mul_x(u128 v){int l=v.lo&1;v.lo=(v.lo>>1)|(v.hi<<63);v.hi>>=1;if(l)v.hi^=0xe100000000000000ULL;return v;}
static u128 gmul_ref(u128 x,u128 h){u128 z={0,0},v=h;for(int i=0;i<64;i++){if((x.hi>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}for(int i=0;i<64;i++){if((x.lo>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}return z;}
static void store_be(unsigned char *p,u128 r){for(int i=7;i>=0;i--){p[i]=r.hi&0xff;r.hi>>=8;}for(int i=7;i>=0;i--){p[8+i]=r.lo&0xff;r.lo>>=8;}}

static inline __m128i gmul(__m128i a, __m128i b){
    __m128i lo  = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i hi  = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i mid = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    lo = _mm_xor_si128(lo, _mm_slli_si128(mid, 8));
    hi = _mm_xor_si128(hi, _mm_srli_si128(mid, 8));
    const __m128i poly = _mm_set_epi32(0, 0, 0, 0xe1000000);
    __m128i r = _mm_clmulepi64_si128(lo, poly, 0x01);
    lo = _mm_xor_si128(lo, _mm_slli_si128(r, 8));
    r = _mm_clmulepi64_si128(lo, poly, 0x00);
    lo = _mm_xor_si128(lo, _mm_srli_si128(r, 8));
    return _mm_xor_si128(lo, hi);
}

int main(){
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(c, EVP_aes_128_ecb(), NULL, key, NULL);
    int l; unsigned char Hb[16], zero[16]={0}; EVP_EncryptUpdate(c, Hb, &l, zero, 16);
    unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=0x30+i;
    unsigned char refb[16]; store_be(refb, gmul_ref(load_be(blk), load_be(Hb)));

    __m128i X = bitrev8(_mm_loadu_si128((__m128i*)blk));
    __m128i H = bitrev8(_mm_loadu_si128((__m128i*)Hb));
    __m128i R = bitrev8(gmul(X, H));
    unsigned char out[16]; _mm_storeu_si128((__m128i*)out, R);
    printf("ref  "); for(int i=0;i<16;i++) printf("%02x", refb[i]); printf("\n");
    printf("simd "); for(int i=0;i<16;i++) printf("%02x", out[i]); printf(" match=%d\n", memcmp(out,refb,16)==0);

    /* also test a second random-ish block to be sure */
    for(int i=0;i<16;i++) blk[i]=0xa5^i;
    store_be(refb, gmul_ref(load_be(blk), load_be(Hb)));
    X = bitrev8(_mm_loadu_si128((__m128i*)blk));
    R = bitrev8(gmul(X, H));
    _mm_storeu_si128((__m128i*)out, R);
    printf("ref2 "); for(int i=0;i<16;i++) printf("%02x", refb[i]); printf("\n");
    printf("sim2 "); for(int i=0;i<16;i++) printf("%02x", out[i]); printf(" match=%d\n", memcmp(out,refb,16)==0);
    return 0;
}
EOF
