        unsigned char out[16]; _mm_storeu_si128((__m128i*)out, R);
        if (memcmp(out, refb, 16)!=0){ ok=0; printf("FAIL at %d\n", t); break; }
    }
    printf("correctness %s\n", ok?"OK":"FAIL");

    size_t N=60000ULL*1024;
    unsigned char *buf=aligned_alloc(64,N); memset(buf,0x42,N);
    double t0=now();
    __m128i acc=_mm_setzero_si128();
    for(size_t i=0;i<N;i+=16){
        __m128i x=bitrev8(_mm_loadu_si128((__m128i*)(buf+i)));
        acc=gmul(_mm_xor_si128(acc,x), Hr);
    }
    double dt=now()-t0;
    unsigned char sink[16]; _mm_storeu_si128((__m128i*)sink, acc);
    printf("1x ghash %.4f s (%.0f MB/s) sink=%02x\n", dt, (N/1e6)/dt, sink[0]);

    /* 8-way aggregated GHASH: y = (((m1*H^8 + m2*H^7) ... ) */
    __m128i Hp[9]; Hp[1]=Hr;
    for(int i=2;i<=8;i++) Hp[i]=gmul(Hp[i-1], Hr);
    t0=now();
    __m128i a[8]; for(int k=0;k<8;k++) a[k]=_mm_setzero_si128();
    for(size_t i=0;i+128<=N;i+=128){
        __m128i xs[8];
        for(int k=0;k<8;k++) xs[k]=bitrev8(_mm_loadu_si128((__m128i*)(buf+i+16*k)));
        /* This is a throughput probe only (not the chained reduction); measure clmul bandwidth */
        __m128i los[8], his[8], mids[8];
        for(int k=0;k<8;k++){ los[k]=_mm_clmulepi64_si128(xs[k],Hp[8-k],0x00); his[k]=_mm_clmulepi64_si128(xs[k],Hp[8-k],0x11); }
