        for(int k=0;k<8;k++) a[k]=_mm_xor_si128(los[k], _mm_xor_si128(his[k], mids[k]));
    }
    dt=now()-t0;
    printf("8x ghash %.4f s (%.0f MB/s)\n", dt, (N/1e6)/dt);
    return 0;
}
