       low-bit-first 64-bit lanes: lane bit k = x^(k) for k in 0..63 (which are the TOP bytes). */
    /* Convert x,h from (hi=top bits) into low-bit-first where bit 0 = x^0 = top bit of hi. */
    uint64_t xl = 0, xh = 0, hl = 0, hh = 0;
    for (int s = 0; s < 64; s++) { /* s=0 -> x.hi bit 63 */
        if ((x.hi >> (63-s)) & 1) xl |= (uint64_t)1 << s;
        if ((h.hi >> (63-s)) & 1) hl |= (uint64_t)1 << s;
        if ((x.lo >> (63-s)) & 1) xh |= (uint64_t)1 << s;
        if ((h.lo >> (63-s)) & 1) hh |= (uint64_t)1 << s;
    }
    /* 256-bit product, bit k = x^k */
    unsigned __int128 p0 = (unsigned __int128)xl * hl;       /* bits 0..127 */
    unsigned __int128 p1 = (unsigned __int128)xl * hh;       /* bits 64..191 */
    unsigned __int128 p2 = (unsigned __int128)xh * hl;       /* bits 64..191 */
    unsigned __int128 p3 = (unsigned __int128)xh * hh;       /* bits 128..255 */
    uint64_t w[4] = {0,0,0,0};
    w[0] ^= (uint64_t)p0; w[1] ^= (uint64_t)(p0>>64);
    w[1] ^= (uint64_t)p1; w[2] ^= (uint64_t)(p1>>64);
    w[1] ^= (uint64_t)p2; w[2] ^= (uint64_t)(p2>>64);
    w[2] ^= (uint64_t)p3; w[3] ^= (uint64_t)(p3>>64);
    /* reduce: bit (128+j) -> j, j+1, j+2, j+7 */
    for (int lane = 3; lane >= 2; lane--) {
        uint64_t v = w[lane];
        int base = 64*(lane-2); /* bit position offset: lane2 -> bit128 -> j=0 -> +0 */
        int sh[4] = {0,1,2,7};
        for (int s = 0; s < 4; s++) {
            int pos = base + sh[s];
            int dst = pos/64; int off = pos%64;
