    u128 r = {0,0};
    for (int s = 0; s < 64; s++) {
        if ((w[0] >> s) & 1) r.hi |= (uint64_t)1 << (63-s);
        if ((w[1] >> s) & 1) r.lo |= (uint64_t)1 << (63-s);
