static u128 xor128(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
static u128 mul_x(u128 v){int l=v.lo&1;v.lo=(v.lo>>1)|(v.hi<<63);v.hi>>=1;if(l)v.hi^=0xe100000000000000ULL;return v;}
static u128 gmul_ref(u128 x,u128 h){u128 z={0,0},v=h;for(int i=0;i<64;i++){if((x.hi>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}for(int i=0;i<64;i++){if((x.lo>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}return z;}

/* Multiplication with bit k = x^k (lo bit 0 = x^0). Reduction: x^128 = x^7 + x^2 + x + 1. */
static u128 gmul_v1(u128 x, u128 h){
    uint64_t xw0=x.lo, xw1=x.hi, hw0=h.lo, hw1=h.hi;
    unsigned __int128 p0=(unsigned __int128)xw0*hw0, p1=(unsigned __int128)xw0*hw1, p2=(unsigned __int128)xw1*hw0, p3=(unsigned __int128)xw1*hw1;
    uint64_t w[4]={0,0,0,0};
    w[0]^=(uint64_t)p0; w[1]^=(uint64_t)(p0>>64);
    w[1]^=(uint64_t)p1; w[2]^=(uint64_t)(p1>>64);
    w[1]^=(uint64_t)p2; w[2]^=(uint64_t)(p2>>64);
    w[2]^=(uint64_t)p3; w[3]^=(uint64_t)(p3>>64);
    for(int lane=3;lane>=2;lane--){uint64_t v=w[lane];int base=64*(lane-2);int sh[4]={0,1,2,7};
        for(int s=0;s<4;s++){int pos=base+sh[s];int dst=pos/64,off=pos%64;w[dst]^=v<<off;if(off)w[dst+1]^=v>>(64-off);}w[lane]=0;}
    u128 r; r.lo=w[0]; r.hi=w[1]; return r;
}

/* bit k = x^(127-k): top-bit-first. lo here holds x^127..x^64 reversed? Let's define explicitly:
   mw[0] bit k = x^(127-k) for k=0..63 i.e. mw[0] = hi with bits reversed? Simpler: just mirror the
   reduction constant. x^128 = x^127 + x^126 + x^121 + x^120 in the top-bit-first numbering?
   Derive from the known identity and test both directions. */
static u128 gmul_v2(u128 x, u128 h){
    /* bit k = x^(127-k): use hi bit63 = x^127 so mw bit (127-k) ... just feed hi,lo swapped-endian.
       Represent value as bit k = x^(127-k): lane0 (w[0]) bit k = x^(127-k), k=0..63 => w[0] = byte-reversed hi.
       Easiest correct transform: reverse all 128 bits, multiply with v1, reverse back. */
    uint64_t rev(uint64_t v){uint64_t y=0;for(int i=0;i<64;i++){y=(y<<1)|(v&1);v>>=1;}return y;}
    u128 xr; xr.lo=rev(x.hi); xr.hi=rev(x.lo);
    u128 hr; hr.lo=rev(h.hi); hr.hi=rev(h.lo);
    u128 p = gmul_v1(xr, hr);
    u128 r; r.lo=rev(p.hi); r.hi=rev(p.lo); return r;
}
int main(){
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(c, EVP_aes_128_ecb(), NULL, key, NULL);
    int l; unsigned char Hb[16], zero[16]={0}; EVP_EncryptUpdate(c, Hb, &l, zero, 16);
    u128 H=load_be(Hb);
