        unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=(t*17+i*3)&0xff;
        u128 ref=gmul_ref(load_be(blk),H);
        u128 X=load_be(blk);
        if(gmul_v1(X,H).hi!=ref.hi||gmul_v1(X,H).lo!=ref.lo) ok1=0;
        if(gmul_v2(X,H).hi!=ref.hi||gmul_v2(X,H).lo!=ref.lo) ok2=0;
    }
    printf("v1 (bit0=x^0, reduce +0+1+2+7) %s\n", ok1?"OK":"FAIL");
    printf("v2 (bit-reversed v1)           %s\n", ok2?"OK":"FAIL");
    return 0;
}
