   x.hi bit 63 = x^127, x.hi bit 0 = x^64, x.lo bit 63 = x^63, x.lo bit 0 = x^0.
   So the limb holding x^0..x^63 is x.lo but BIT-REVERSED within the limb (bit 0 of limb = x^63).
   Use explicit: power p lives at limb p/64, bit p%64. */
static uint64_t bitreverse64(uint64_t v){uint64_t y=0;for(int i=0;i<64;i++){y=(y<<1)|(v&1);v>>=1;}return y;}

static u128 gmul_fast(u128 x, u128 h){
    /* limb L0 bit k = x^k. x.lo bit k = x^(63-k), so L0 = bitreverse(x.lo)? 
       x.lo bit 0 = x^0, x.lo bit 63 = x^63. So L0 = x.lo directly, L1 = x.hi. */
    uint64_t x0=x.lo, x1=x.hi, h0=h.lo, h1=h.hi;
    unsigned __int128 p0=(unsigned __int128)x0*h0; /* x^0..127 */
    unsigned __int128 p1=(unsigned __int128)x0*h1; /* x^64..191 */
    unsigned __int128 p2=(unsigned __int128)x1*h0; /* x^64..191 */
    unsigned __int128 p3=(unsigned __int128)x1*h1; /* x^128..255 */
    uint64_t w[4]={0,0,0,0};
    w[0]^=(uint64_t)p0; w[1]^=(uint64_t)(p0>>64);
    w[1]^=(uint64_t)p1; w[2]^=(uint64_t)(p1>>64);
    w[1]^=(uint64_t)p2; w[2]^=(uint64_t)(p2>>64);
    w[2]^=(uint64_t)p3; w[3]^=(uint64_t)(p3>>64);
    /* But the reference product_ref used the same convention and did NOT match the integer product.
       So x.lo bit k is NOT x^k. Check: load_be puts p[15] into lo bits 0..7. p[15] bit 0 = x^0,
       and p[15] bit 0 lands in lo bit 0. So lo bit 0 = x^0. That IS the convention. The mismatch
       must be elsewhere. Let's just compare limbs here. */
    (void)bitreverse64;
    u128 r; r.lo=w[0]; r.hi=w[1]; return r;
}
int main(){
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(c, EVP_aes_128_ecb(), NULL, key, NULL);
    int l; unsigned char Hb[16], zero[16]={0}; EVP_EncryptUpdate(c, Hb, &l, zero, 16);
