static u128 xor128(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
static u128 mul_x(u128 v){int l=v.lo&1;v.lo=(v.lo>>1)|(v.hi<<63);v.hi>>=1;if(l)v.hi^=0xe100000000000000ULL;return v;}
static u128 gmul_ref(u128 x,u128 h){u128 z={0,0},v=h;for(int i=0;i<64;i++){if((x.hi>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}for(int i=0;i<64;i++){if((x.lo>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}return z;}
static uint64_t brev(uint64_t v){uint64_t y=0;for(int i=0;i<64;i++){y=(y<<1)|(v&1);v>>=1;}return y;}

/* L0 bit k = x^(63-k) given raw lo... we want limb bit k = x^k.
   x.lo bit k = x^(63-k)? No: x.lo bit 0 = byte15 bit0 = x^0. So x.lo bit k = x^k.
   Confirmed by print: X.lo = 0x38393a3b3c3d3e3f, byte15=0x3f at bits 0..7. So bit k = x^k. */
static void prod(u128 x,u128 h,uint64_t w[4]){
    unsigned __int128 p0=(unsigned __int128)x.lo*h.lo;
    unsigned __int128 p1=(unsigned __int128)x.lo*h.hi;
    unsigned __int128 p2=(unsigned __int128)x.hi*h.lo;
    unsigned __int128 p3=(unsigned __int128)x.hi*h.hi;
    w[0]=(uint64_t)p0; w[1]=(uint64_t)(p0>>64); w[2]=0; w[3]=0;
    w[1]^=(uint64_t)p1; w[2]^=(uint64_t)(p1>>64);
    w[1]^=(uint64_t)p2; w[2]^=(uint64_t)(p2>>64);
    w[2]^=(uint64_t)p3; w[3]^=(uint64_t)(p3>>64);
}
static void prod_ref(u128 x,u128 h,uint64_t w[4]){
    memset(w,0,32);
    for(int i=0;i<128;i++){int xb=(i<64)?(x.lo>>i)&1:(x.hi>>(i-64))&1; if(!xb)continue;
        for(int j=0;j<128;j++){int hb=(j<64)?(h.lo>>j)&1:(h.hi>>(j-64))&1; if(!hb)continue;
