    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(c, EVP_aes_128_ecb(), NULL, key, NULL);
    int l; unsigned char Hb[16], zero[16]={0}; EVP_EncryptUpdate(c, Hb, &l, zero, 16);
    u128 H=load_be(Hb);
    unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=0x30+i;
    u128 X=load_be(blk);
    uint64_t a[4],b[4]; prod(X,H,a); prod_ref(X,H,b);
    printf("match %d\n", memcmp(a,b,32)==0);
    printf("fast %016llx %016llx %016llx %016llx\n",(unsigned long long)a[0],(unsigned long long)a[1],(unsigned long long)a[2],(unsigned long long)a[3]);
    printf("ref  %016llx %016llx %016llx %016llx\n",(unsigned long long)b[0],(unsigned long long)b[1],(unsigned long long)b[2],(unsigned long long)b[3]);
    /* Which bit of X.lo corresponds to x^0? gmul_ref processes x.hi bit63 first as the x^127 coefficient
       and shifts v right each step, xoring 0xe1 into the TOP when the low bit falls off. So after 127
       steps v = H*x^0 and the last coefficient consumed is x.lo bit 0. So x.lo bit 0 = x^0. Consistent.
