#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <openssl/evp.h>

static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}

typedef struct { uint64_t hi, lo; } u128;
static u128 load_be(const unsigned char *p){u128 r={0,0};for(int i=0;i<8;i++)r.hi=(r.hi<<8)|p[i];for(int i=0;i<8;i++)r.lo=(r.lo<<8)|p[8+i];return r;}
static void store_be(unsigned char *p,u128 r){for(int i=7;i>=0;i--){p[i]=r.hi&0xff;r.hi>>=8;}for(int i=7;i>=0;i--){p[8+i]=r.lo&0xff;r.lo>>=8;}}
static u128 xor128(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
static u128 mul_x(u128 v){int l=v.lo&1;v.lo=(v.lo>>1)|(v.hi<<63);v.hi>>=1;if(l)v.hi^=0xe100000000000000ULL;return v;}
static u128 gmul_ref(u128 x,u128 h){u128 z={0,0},v=h;for(int i=0;i<64;i++){if((x.hi>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}for(int i=0;i<64;i++){if((x.lo>>(63-i))&1)z=xor128(z,v);v=mul_x(v);}return z;}

/* clmul product, bit k = x^k (lo bit 0 = x^0 = byte15 bit0), reduce x^128 = x^7+x^2+x+1. */
static inline u128 gmul_clmul(u128 x, u128 h){
    __m128i a = _mm_set_epi64x(x.hi, x.lo);
    __m128i b = _mm_set_epi64x(h.hi, h.lo);
    __m128i z0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01), _mm_clmulepi64_si128(a, b, 0x10));
    __m128i lo = _mm_xor_si128(z0, _mm_slli_si128(z1, 8));
    __m128i hi = _mm_xor_si128(z2, _mm_srli_si128(z1, 8));
    uint64_t L[2], Hh[2];
    _mm_storeu_si128((__m128i*)L, lo);
    _mm_storeu_si128((__m128i*)Hh, hi);
    uint64_t w[4] = {L[0], L[1], Hh[0], Hh[1]};
    for (int lane = 3; lane >= 2; lane--) {
        uint64_t v = w[lane];
        int base = 64*(lane-2);
        int s[4] = {0,1,2,7};
        for (int k = 0; k < 4; k++) {
            int pos = base + s[k];
            int dst = pos/64, off = pos%64;
            w[dst] ^= v << off;
            if (off) w[dst+1] ^= v >> (64-off);
        }
        w[lane] = 0;
    }
    u128 r; r.lo = w[0]; r.hi = w[1];
    return r;
}

int main(){
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(c, EVP_aes_128_ecb(), NULL, key, NULL);
    int l; unsigned char Hb[16], zero[16]={0}; EVP_EncryptUpdate(c, Hb, &l, zero, 16);
    u128 H = load_be(Hb);
    int ok=1;
    for(int t=0;t<300;t++){
        unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=(t*17+i*3)&0xff;
        u128 ref=gmul_ref(load_be(blk),H), got=gmul_clmul(load_be(blk),H);
        if(ref.hi!=got.hi||ref.lo!=got.lo){ok=0;unsigned char a[16],b[16];store_be(a,ref);store_be(b,got);
            printf("FAIL t=%d\nref ",t);for(int i=0;i<16;i++)printf("%02x",a[i]);
            printf("\ngot ");for(int i=0;i<16;i++)printf("%02x",b[i]);printf("\n");break;}
    }
    printf("gmul_clmul %s\n", ok?"OK":"FAIL");
    return 0;
}
EOF
