/* gmul_ref(x^{127-k}, H) == H * x^k reduced, in the convention where we process MSB first.
   x^{127} corresponds to x.hi bit 63. So gmul_ref(x^{127-k}) = reduce(H << k) where << is toward LSB? 
   Let's just compute, for each excess bit position j (128..254), which output bits it maps to,
   by multiplying the single-bit value x^(127) by x^(j-127) ... simpler: the reduction of bit position
   p (>=128) equals gmul_ref of the input whose only effect is that bit. We can get it as
   gmul_ref(x^{p}) but our domain is only 128 bits. Instead compute the unreduced single-bit product
   contribution analytically: bit p reduces to gmul_ref(e_{p-128}) * ??? 
   Direct: reduction of x^p (p>=128) = x^{p-128} * (x^7+x^2+x+1) or the other convention.
   Just evaluate gmul_ref for x^127 (hi bit63) against h = x^k and see. */
int main(){
    /* For h = x^0 (lo bit 0) and x = x^127 (hi bit 63): product = x^127, no reduction. */
    u128 x={0,0}, h={0,0};
    x.hi = (uint64_t)1<<63; /* x^127 */
    h.lo = 1;               /* x^0 */
    u128 r = gmul_ref(x,h);
    printf("x^127 * x^0 -> lo=%016llx hi=%016llx (expect hi bit63)\n",(unsigned long long)r.lo,(unsigned long long)r.hi);
    /* x^127 * x^1 = x^128, which MUST be reduced. h = x^1 = lo bit 1. */
    h.lo = 2;
    r = gmul_ref(x,h);
    printf("x^127 * x^1 = x^128 -> lo=%016llx hi=%016llx\n",(unsigned long long)r.lo,(unsigned long long)r.hi);
    /* x^127 * x^2 = x^129 */
    h.lo = 4;
    r = gmul_ref(x,h);
    printf("x^129 -> lo=%016llx hi=%016llx\n",(unsigned long long)r.lo,(unsigned long long)r.hi);
    /* x^127 * x^8 = x^135 */
    h.lo = 1<<8;
    r = gmul_ref(x,h);
    printf("x^135 -> lo=%016llx hi=%016llx\n",(unsigned long long)r.lo,(unsigned long long)r.hi);
    return 0;
}
