    u128 H=load_be(Hb);
    unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=0x30+i;
    u128 X=load_be(blk);
    u128 a=gmul_ref(X,H), b=gmul_nist(X,H);
    unsigned char ab[16],bb[16]; store_be(ab,a); store_be(bb,b);
    printf("ref  "); for(int i=0;i<16;i++) printf("%02x",ab[i]); printf("\n");
    printf("nist "); for(int i=0;i<16;i++) printf("%02x",bb[i]); printf("\n");
    printf("match %d\n", memcmp(ab,bb,16)==0);

    /* Now the real test: compare gmul_nist against an actual AES-GCM tag (done before, gmul_ref matched).
       Since ref==nist here, both are correct. So my reduction derivation must have a bug, not the multiply.
       Recompute x^128 = x^127 * x^1 with nist and show raw bytes. */
    u128 x127={0x8000000000000000ULL, 0};
    u128 x1={0, 2};
