#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <openssl/evp.h>

static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}
typedef struct { uint64_t hi, lo; } u128;
static u128 load_be(const unsigned char *p){u128 r={0,0};for(int i=0;i<8;i++)r.hi=(r.hi<<8)|p[i];for(int i=0;i<8;i++)r.lo=(r.lo<<8)|p[8+i];return r;}
static void store_be(unsigned char *p,u128 r){for(int i=7;i>=0;i--){p[i]=r.hi&0xff;r.hi>>=8;}for(int i=7;i>=0;i--){p[8+i]=r.lo&0xff;r.lo>>=8;}}
static u128 xor128(u128 a,u128 b){a.hi^=b.hi;a.lo^=b.lo;return a;}
static u128 gmul_ref(u128 x,u128 h){u128 Z={0,0},V=h;for(int i=0;i<128;i++){int bit=(i<64)?(x.hi>>(63-i))&1:(x.lo>>(127-i))&1;if(bit)Z=xor128(Z,V);int l=V.lo&1;V.lo=(V.lo>>1)|(V.hi<<63);V.hi>>=1;if(l)V.hi^=0xe100000000000000ULL;}return Z;}

/* Carryless product with bit k = x^k where x^1 = lo bit 1 (the field indeterminate) and x^0 = lo bit 0.
   Degree grows toward the MSB. x^128 reduces to x^7+x^2+x+1 = 0xe1 in the LOW byte.
   clmul gives bit k = x^k directly (lo bit 0 = x^0). Product bits 128..255 fold down:
   bit (128+j) -> bits j, j+1, j+2, j+7. */
static inline u128 gmul(u128 x, u128 h){
    __m128i a=_mm_set_epi64x(x.hi,x.lo), b=_mm_set_epi64x(h.hi,h.lo);
    __m128i z0=_mm_clmulepi64_si128(a,b,0x00);
    __m128i z2=_mm_clmulepi64_si128(a,b,0x11);
    __m128i z1=_mm_xor_si128(_mm_clmulepi64_si128(a,b,0x01),_mm_clmulepi64_si128(a,b,0x10));
    __m128i lo=_mm_xor_si128(z0,_mm_slli_si128(z1,8));
    __m128i hi=_mm_xor_si128(z2,_mm_srli_si128(z1,8));
    uint64_t L[2],H[2]; _mm_storeu_si128((__m128i*)L,lo); _mm_storeu_si128((__m128i*)H,hi);
    uint64_t w0=L[0], w1=L[1], w2=H[0], w3=H[1];
    /* fold w3 (bits 192..255) then w2 (bits 128..191): bit (128+j) -> j, j+1, j+2, j+7 */
    for(int pass=0;pass<2;pass++){
        uint64_t v = pass? w2 : w3;
        int base = pass? 0 : 64; /* j offset */
        int s[4]={0,1,2,7};
        for(int k=0;k<4;k++){
            int pos=base+s[k]; int dst=pos/64, off=pos%64;
            if(dst==0) w0^=v<<off; else w1^=v<<off;
            if(off){ if(dst+1==1) w1^=v>>(64-off); else w2^=v>>(64-off); }
        }
        if(pass) w2=0; else w3=0;
    }
    u128 r; r.lo=w0; r.hi=w1; return r;
}

int main(){
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    EVP_CIPHER_CTX *c=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(c, EVP_aes_128_ecb(), NULL, key, NULL);
    int l; unsigned char Hb[16], zero[16]={0}; EVP_EncryptUpdate(c, Hb, &l, zero, 16);
    u128 H=load_be(Hb);
    int ok=1;
    for(int t=0;t<400;t++){
        unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=(t*17+i*3)&0xff;
        u128 ref=gmul_ref(load_be(blk),H), got=gmul(load_be(blk),H);
        if(ref.hi!=got.hi||ref.lo!=got.lo){ok=0;unsigned char a[16],b[16];store_be(a,ref);store_be(b,got);
            printf("FAIL t=%d\nref ",t);for(int i=0;i<16;i++)printf("%02x",a[i]);
            printf("\ngot ");for(int i=0;i<16;i++)printf("%02x",b[i]);printf("\n");break;}
    }
    printf("gmul %s\n", ok?"OK":"FAIL");

    if(ok){
        size_t N=60000ULL*1024; unsigned char *buf=malloc(N); memset(buf,0x42,N);
        double t0=now(); u128 y={0,0};
        for(size_t i=0;i<N;i+=16) y=gmul(xor128(y,load_be(buf+i)),H);
        double dt=now()-t0; unsigned char s[16]; store_be(s,y);
        printf("1x %.4f s (%.0f MB/s) %02x\n",dt,(N/1e6)/dt,s[0]);
    }
    return 0;
}
EOF
