/* Reflected reduction: product bit p (p = i+j in clmul numbering) reduces to bit (127-p) plus folds.
   Implement by reflecting both inputs (bit p <-> bit 127-p), doing the standard x^128=x^7+x^2+x+1
   reduction, and reflecting the output back. */
static uint64_t brev(uint64_t v){uint64_t y=0;for(int i=0;i<64;i++){y=(y<<1)|(v&1);v>>=1;}return y;}
static u128 reflect(u128 a){u128 r; r.lo=brev(a.hi); r.hi=brev(a.lo); return r;}

static u128 gmul_refl(u128 x,u128 h){
    x=reflect(x); h=reflect(h);
    __m128i a=_mm_set_epi64x(x.hi,x.lo), b=_mm_set_epi64x(h.hi,h.lo);
    __m128i z0=_mm_clmulepi64_si128(a,b,0x00);
    __m128i z2=_mm_clmulepi64_si128(a,b,0x11);
    __m128i z1=_mm_xor_si128(_mm_clmulepi64_si128(a,b,0x01),_mm_clmulepi64_si128(a,b,0x10));
