#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <openssl/evp.h>

static double now(){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return t.tv_sec+t.tv_nsec/1e9;}

#define NTHREADS 4

static uint64_t brev(uint64_t v){uint64_t y=0;for(int i=0;i<64;i++){y=(y<<1)|(v&1);v>>=1;}return y;}

/* GHASH multiply: reflect, clmul, reduce x^128=x^7+x^2+x+1, reflect back. */
static inline __m128i reflect(__m128i x){
    uint64_t l[2]; _mm_storeu_si128((__m128i*)l, x);
    uint64_t o[2]; o[0]=brev(l[1]); o[1]=brev(l[0]);
    return _mm_loadu_si128((__m128i*)o);
}
static inline __m128i gmul(__m128i x, __m128i h){
    x=reflect(x); h=reflect(h);
    __m128i z0=_mm_clmulepi64_si128(x,h,0x00);
    __m128i z2=_mm_clmulepi64_si128(x,h,0x11);
    __m128i z1=_mm_xor_si128(_mm_clmulepi64_si128(x,h,0x01),_mm_clmulepi64_si128(x,h,0x10));
    __m128i lo=_mm_xor_si128(z0,_mm_slli_si128(z1,8));
    __m128i hi=_mm_xor_si128(z2,_mm_srli_si128(z1,8));
    uint64_t L[2],H[2]; _mm_storeu_si128((__m128i*)L,lo); _mm_storeu_si128((__m128i*)H,hi);
    uint64_t w0=L[0],w1=L[1],w2=H[0],w3=H[1];
    uint64_t *ww[4]={&w0,&w1,&w2,&w3};
    for(int lane=3;lane>=2;lane--){uint64_t v=*ww[lane];int base=64*(lane-2);int s[4]={0,1,2,7};
        for(int k=0;k<4;k++){int pos=base+s[k];int dst=pos/64,off=pos%64;*ww[dst]^=v<<off;if(off)*ww[dst+1]^=v>>(64-off);}*ww[lane]=0;}
    uint64_t r[2]={w0,w1};
    return reflect(_mm_loadu_si128((__m128i*)r));
}

typedef struct { const unsigned char *in; unsigned char *out; size_t off, len; unsigned char key[16]; unsigned char iv[16]; } job_t;
static void *ctr_worker(void *arg){
    job_t *j=arg;
    EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, j->key, j->iv);
    int l=0; size_t done=0;
    while(done<j->len){int chunk=(j->len-done>1<<30)?1<<30:(int)(j->len-done);
        EVP_EncryptUpdate(ctx, j->out+j->off+done, &l, j->in+j->off+done, chunk); done+=l;}
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

/* add 'blocks' (big-endian) to a 16-byte counter */
static void ctr_add(unsigned char ctr[16], uint64_t blocks){
    uint64_t lo = ((uint64_t)ctr[8]<<56)|((uint64_t)ctr[9]<<48)|((uint64_t)ctr[10]<<40)|((uint64_t)ctr[11]<<32)|
                  ((uint64_t)ctr[12]<<24)|((uint64_t)ctr[13]<<16)|((uint64_t)ctr[14]<<8)|ctr[15];
    uint64_t hi = ((uint64_t)ctr[0]<<56)|((uint64_t)ctr[1]<<48)|((uint64_t)ctr[2]<<40)|((uint64_t)ctr[3]<<32)|
                  ((uint64_t)ctr[4]<<24)|((uint64_t)ctr[5]<<16)|((uint64_t)ctr[6]<<8)|ctr[7];
    lo += blocks; if(lo < blocks) hi++;
    for(int i=7;i>=0;i--){ctr[i]=hi&0xff;hi>>=8;}
    for(int i=15;i>=8;i--){ctr[i]=lo&0xff;lo>>=8;}
