static void gcm_encrypt(const unsigned char *key, const unsigned char *iv, const unsigned char *aad, size_t aad_len,
                        const unsigned char *pt, unsigned char *ct, size_t len, unsigned char tag[16]){
    /* H = AES_K(0) */
    unsigned char zero[16]={0}, H[16];
    EVP_CIPHER_CTX *ec=EVP_CIPHER_CTX_new();
    int l; EVP_EncryptInit_ex(ec, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_EncryptUpdate(ec, H, &l, zero, 16);
    EVP_CIPHER_CTX_free(ec);
    __m128i Hr=_mm_loadu_si128((__m128i*)H);

