    unsigned char J0[16]; memcpy(J0, iv, 12); J0[12]=0;J0[13]=0;J0[14]=0;J0[15]=1;
    unsigned char ctr0[16]; memcpy(ctr0, J0, 16); ctr_add(ctr0, 1);

    /* parallel CTR */
    pthread_t th[NTHREADS]; job_t jobs[NTHREADS];
    size_t blocks = (len+15)/16;
    size_t chunk = ((blocks/NTHREADS)+0) ; /* in blocks */
    size_t base = 0;
    int nt = NTHREADS;
    for(int t=0;t<nt;t++){
        size_t nb = (t==nt-1)? (blocks-base) : blocks/nt;
        jobs[t].in=pt; jobs[t].out=ct; jobs[t].off=base*16;
        size_t end = (base+nb)*16; if(end>len) end=len;
        jobs[t].len = end - jobs[t].off;
        memcpy(jobs[t].key, key, 16);
        memcpy(jobs[t].iv, ctr0, 16);
        ctr_add(jobs[t].iv, base);
        pthread_create(&th[t], NULL, ctr_worker, &jobs[t]);
        base += nb;
    }
    for(int t=0;t<nt;t++) pthread_join(th[t], NULL);

    /* GHASH over AAD then ciphertext */
    __m128i y=_mm_setzero_si128();
    size_t i=0;
    for(;i+16<=aad_len;i+=16){ __m128i b=_mm_loadu_si128((__m128i*)(aad+i)); y=gmul(_mm_xor_si128(y,b),Hr); }
    if(i<aad_len){ unsigned char blk[16]={0}; memcpy(blk,aad+i,aad_len-i); __m128i b=_mm_loadu_si128((__m128i*)blk); y=gmul(_mm_xor_si128(y,b),Hr); }
    i=0;
    for(;i+16<=len;i+=16){ __m128i b=_mm_loadu_si128((__m128i*)(ct+i)); y=gmul(_mm_xor_si128(y,b),Hr); }
    if(i<len){ unsigned char blk[16]={0}; memcpy(blk,ct+i,len-i); __m128i b=_mm_loadu_si128((__m128i*)blk); y=gmul(_mm_xor_si128(y,b),Hr); }
    unsigned char lb[16]={0};
    uint64_t al=aad_len*8, cl=len*8;
    for(int k=0;k<8;k++){lb[7-k]=al&0xff;al>>=8;}
    for(int k=0;k<8;k++){lb[15-k]=cl&0xff;cl>>=8;}
    __m128i b=_mm_loadu_si128((__m128i*)lb);
    y=gmul(_mm_xor_si128(y,b),Hr);
    unsigned char s[16]; _mm_storeu_si128((__m128i*)s, y);

    /* tag = S xor AES_K(J0) */
    unsigned char EJ0[16];
    ec=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ec, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_EncryptUpdate(ec, EJ0, &l, J0, 16);
    EVP_CIPHER_CTX_free(ec);
    for(int k=0;k<16;k++) tag[k]=s[k]^EJ0[k];
}

int main(){
    size_t N=1024*1024;
    unsigned char *pt=malloc(N), *ct=malloc(N), *ref=malloc(N+16);
    for(size_t i=0;i<N;i++) pt[i]=i*3+7;
    unsigned char key[16]; for(int i=0;i<16;i++) key[i]=i+1;
    unsigned char iv[12]; for(int i=0;i<12;i++) iv[i]=0x10+i;
    unsigned char aad[32]; memset(aad,0xab,32);
    unsigned char tag[16], tagref[16];
    gcm_encrypt(key, iv, aad, 32, pt, ct, N, tag);

    EVP_CIPHER_CTX *g=EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(g, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(g, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(g, NULL, NULL, key, iv);
    int l, tot=0; EVP_EncryptUpdate(g, NULL, &l, aad, 32);
    EVP_EncryptUpdate(g, ref, &l, pt, (int)N); tot=l;
    EVP_EncryptFinal_ex(g, ref+tot, &l);
    EVP_CIPHER_CTX_ctrl(g, EVP_CTRL_GCM_GET_TAG, 16, tagref);
    printf("ct match %d  tag match %d\n", memcmp(ct,ref,N)==0, memcmp(tag,tagref,16)==0);
    if(memcmp(tag,tagref,16)){printf("tag ");for(int i=0;i<16;i++)printf("%02x",tag[i]);printf("\nref ");for(int i=0;i<16;i++)printf("%02x",tagref[i]);printf("\n");}

    /* throughput on 60MB */
    size_t M=60000ULL*1024; unsigned char *big=malloc(M), *bigct=malloc(M);
    memset(big,0x42,M);
    double t0=now();
    gcm_encrypt(key, iv, aad, 32, big, bigct, M, tag);
    double dt=now()-t0;
    printf("60MB parallel: %.4f s (%.0f MB/s)\n", dt, (M/1e6)/dt);

    /* EVP baseline */
    g=EVP_CIPHER_CTX_new();
    t0=now();
    EVP_EncryptInit_ex(g, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(g, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(g, NULL, NULL, key, iv);
    EVP_EncryptUpdate(g, NULL, &l, aad, 32);
    size_t done=0; while(done<M){int chunk=(M-done>1<<30)?1<<30:(int)(M-done); EVP_EncryptUpdate(g, bigct+done, &l, big+done, chunk); done+=l;}
    EVP_EncryptFinal_ex(g, bigct+done, &l);
    dt=now()-t0;
    printf("60MB EVP:      %.4f s (%.0f MB/s)\n", dt, (M/1e6)/dt);
    return 0;
}
