int main(){
    for(int i=0;i<256;i++){int r=0;for(int b=0;b<8;b++)r|=((i>>b)&1)<<(7-b);BREV[i]=r;}
    unsigned char blk[16]; for(int i=0;i<16;i++) blk[i]=0x30+i;
    /* method A: 64-bit bitreverse + swap (the verified one) */
    uint64_t lo, hi;
    memcpy(&lo, blk, 8); memcpy(&hi, blk+8, 8); /* careful: little endian load */
    /* The verified reflect operated on u128 where lo = load_be's lo = bytes 8..15. Let's replicate exactly. */
    uint64_t be_hi=0, be_lo=0;
